#pragma once

// What the camera mock sends, taken from real captures rather than built
// with the hub's own code (#122): if both sides came from the same
// understanding of the protocol, their mistakes would cancel out.
//
// Sources:
// - pcap/ of https://github.com/pwnb0t/trailcam-automation (PH970S,
//   firmware 2.3.6.5, TrailCam Go app): the ARTEMIS responses in
//   capture_fixtures.cpp (generated by fixtures/extract_fixtures.py), the
//   BLE advertisement and the BLE credentials frame (btsnoop/).
// - Our own TC100 captures: the discovery reply and the first DATA packet,
//   also in test/host/test_udp_packets.cpp.

#include <cstddef>
#include <cstdint>

namespace camera_mock::fixtures
{

// An ARTEMIS response body as captured: Base64(AES-128-CBC(JSON)), followed
// on the wire by `padding` zero bytes. The camera's PayloadLen counts both,
// and in every captured response the padding is 21 bytes (the NUL and 20
// zeros), whatever the length of the Base64.
struct CapturedResponse {
    const char *base64;
    std::size_t padding;
};

// cmdId 0, token 37817828, bat_percent 100.
extern const CapturedResponse kLoginResponse;
// cmdId 512, devId C6:1E:0D:E0:0C:FB, model PH970S, 2925 bytes.
extern const CapturedResponse kDeviceInfoResponse;
// cmdId 768, pageNo 0 and 1, 45 entries each (dir 102, mediaNum 436-347).
extern const CapturedResponse kMediaListPage0Response;
extern const CapturedResponse kMediaListPage1Response;

// The token in kLoginResponse; the hub sends it back in every command.
constexpr std::int64_t kCapturedToken = 37817828;
// Padding of every captured response (see CapturedResponse).
constexpr std::size_t kCapturedPadding = 21;
// Entries per captured media-list page, the app's itemCntPerPage.
constexpr int kCapturedItemsPerPage = 45;

// Camera identity in kDeviceInfoResponse. The camera advertises the same
// MAC in its BLE manufacturer data and the last two bytes in its name.
constexpr std::uint8_t kDevId[6] = {0xc6, 0x1e, 0x0d, 0xe0, 0x0c, 0xfb};
constexpr std::uint16_t kProductId = 104;
constexpr const char *kBleName = "TC100_0CFB";

// Discovery reply (0x42) of our TC100 to the hub's LBCS probe.
// clang-format off
constexpr std::uint8_t kDiscoveryReply[24] = {
    0xf1, 0x42, 0x00, 0x14, 0x4c, 0x42, 0x43, 0x53, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x43, 0x43, 0x43, 0x4a, 0x4a, 0x00, 0x00, 0x00,
};
// clang-format on

// Payload of the camera's first DATA packet (index 0), which it sends on its
// own ~0.4 s after discovery: F1 D0 00 07 D1 00 00 00 "ACK".
constexpr std::uint8_t kFirstDataPayload[3] = {'A', 'C', 'K'};

}  // namespace camera_mock::fixtures
